SELECT
  ((((((((SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.y"))) || ('-'))) || ((CASE WHEN LENGTH(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.m"))) >= 2 THEN SUBSTR(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.m")), 1, 2) ELSE SUBSTR(REPLACE(HEX(ZEROBLOB(2)), '00', '0'), 1, 2 - LENGTH(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.m")))) || SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.m")) END)))) || ('-'))) || ((CASE WHEN LENGTH(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.d"))) >= 2 THEN SUBSTR(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.d")), 1, 2) ELSE SUBSTR(REPLACE(HEX(ZEROBLOB(2)), '00', '0'), 1, 2 - LENGTH(SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.d")))) || SYNALOG_NUMBER_TEXT(JSON_EXTRACT(x_26.value, "$.d")) END))) AS s
FROM
  JSON_EACH(JSON_ARRAY(CASE WHEN (31 < CASE WHEN (12 = 2) THEN CASE WHEN ((((((2023) - (4) * CAST((2023) / NULLIF(4, 0) AS INTEGER))) = 0) AND ((((2023) - (100) * CAST((2023) / NULLIF(100, 0) AS INTEGER))) != 0)) OR ((((2023) - (400) * CAST((2023) / NULLIF(400, 0) AS INTEGER))) = 0)) THEN 29 ELSE 28 END ELSE (CASE WHEN ((12) - (1)) < 0 THEN NULL ELSE JSON_EXTRACT(JSON_ARRAY(31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31), '$[' || ((12) - (1)) || ']') END) END) THEN JSON_OBJECT('y', 2023, 'm', 12, 'd', ((31) + (1))) WHEN (12 < 12) THEN JSON_OBJECT('y', 2023, 'm', ((12) + (1)), 'd', 1) ELSE JSON_OBJECT('y', ((2023) + (1)), 'm', 1, 'd', 1) END)) as x_26;